var t=require("discord.js");module.exports={name:"RouteEmbed",builder:e=>{let i=new t.EmbedBuilder().setColor("Blue").setTitle(`${e.flightNumber}: ${e.origin} \u2192 ${e.destination}`).addFields({name:"Origen",value:e.origin,inline:!0},{name:"Destino",value:e.destination,inline:!0},{name:"Aeronave",value:e.aircraft,inline:!0});if(e.duration){let n=Math.floor(e.duration/60),a=e.duration%60;i.addFields({name:"Duraci\xF3n estimada",value:n>0?`${n} h ${a} min`:`${a} min`,inline:!0})}return i.addFields({name:"Ruta",value:e.route?e.route.slice(0,1024):"Sin ruta definida"}),i}};
